  formatWithCursor(text, opts) {
    opts = normalizeOptions(opts);
    return format(text, opts);
  },

  parse(text, opts, massage) {
    opts = normalizeOptions(opts);
    if (text.includes("\r")) {
      text = text.replace(/\r\n?/g, "\n");
    }
